const quotes = [
  {
    text: "Manifest vi kare, naale kara mehntaan.",
    source: "Karan Aujla",
  },
  {
    text: "Ni roti pakki ni mili te aapan launi sikh li.",
    source: "Karan Aujla",
  },
];

function QuoteCarousel() {
  const [active, setActive] = useState(0);
  const [fade, setFade] = useState(true);

  useEffect(() => {
    const timer = setInterval(() => {
      setFade(false);
      setTimeout(() => {
        setActive((prev) => (prev + 1) % quotes.length);
        setFade(true);
      }, 400);
    }, 4500);
    return () => clearInterval(timer);
  }, []);

  const goTo = (i) => {
    if (i === active) return;
    setFade(false);
    setTimeout(() => {
      setActive(i);
      setFade(true);
    }, 300);
  };

  const q = quotes[active];

  return (
    <div
      style={{
        background: "#0a0a0a",
        padding: "80px 24px",
        textAlign: "center",
        borderTop: "1px solid rgba(212,175,55,0.18)",
        borderBottom: "1px solid rgba(212,175,55,0.18)",
        position: "relative",
        overflow: "hidden",
        minHeight: "300px",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
      }}
    >
      {/* Radial glow */}
      <div
        style={{
          position: "absolute",
          top: "50%",
          left: "50%",
          transform: "translate(-50%,-50%)",
          width: "700px",
          height: "220px",
          background:
            "radial-gradient(ellipse, rgba(212,175,55,0.09) 0%, transparent 70%)",
          pointerEvents: "none",
        }}
      />
      {/* Big decorative quote mark */}
      <div
        style={{
          position: "absolute",
          top: "10px",
          left: "50%",
          transform: "translateX(-50%)",
          fontSize: "140px",
          lineHeight: 1,
          color: "rgba(212,175,55,0.05)",
          fontFamily: "Georgia, serif",
          pointerEvents: "none",
          userSelect: "none",
        }}
      >
        &#10077;
      </div>

      {/* Label */}
      <p
        style={{
          fontSize: "12px",
          color: "#D4AF37",
          letterSpacing: "4px",
          fontWeight: 700,
          marginBottom: "28px",
          textTransform: "uppercase",
          position: "relative",
          zIndex: 1,
        }}
      >
        &mdash; Karan Aujla &mdash;
      </p>

      {/* Animated quote */}
      <div
        style={{
          opacity: fade ? 1 : 0,
          transform: fade ? "translateY(0px)" : "translateY(12px)",
          transition: "opacity 0.4s ease, transform 0.4s ease",
          position: "relative",
          zIndex: 1,
          maxWidth: "820px",
        }}
      >
        <blockquote
          style={{
            fontSize: "clamp(18px, 3vw, 32px)",
            color: "#fff",
            fontWeight: 800,
            lineHeight: 1.55,
            margin: "0 auto 16px",
            fontStyle: "italic",
            letterSpacing: "-0.2px",
          }}
        >
          &ldquo;{q.text}&rdquo;
        </blockquote>
        <p
          style={{
            color: "#555",
            fontSize: "13px",
            letterSpacing: "2.5px",
            textTransform: "uppercase",
            fontWeight: 600,
          }}
        >
          {q.source}
        </p>
      </div>

      {/* Dot indicators */}
      <div
        style={{
          display: "flex",
          gap: "10px",
          marginTop: "36px",
          position: "relative",
          zIndex: 1,
        }}
      >
        {quotes.map((_, i) => (
          <button
            key={i}
            onClick={() => goTo(i)}
            style={{
              width: i === active ? "30px" : "8px",
              height: "8px",
              borderRadius: "999px",
              border: "none",
              background:
                i === active ? "#D4AF37" : "rgba(255,255,255,0.15)",
              cursor: "pointer",
              padding: 0,
              transition: "all 0.35s ease",
              boxShadow:
                i === active ? "0 0 12px rgba(212,175,55,0.7)" : "none",
            }}
          />
        ))}
      </div>
    </div>
  );
}

